<template><div><p class="ui-note">{{title||'附件'}}<span v-if="!ids.length">：未提供</span></p><div v-for="(id,index) in ids" :key="id" class="ui-toolbar"><div><span>{{purposeName}} {{index+1}}</span><div class="ui-meta">编号 {{id}}<template v-if="metadata[id]"> · {{metadata[id].mimeType==='application/pdf'?'PDF':metadata[id].mimeType}} · {{metadata[id].size}} 字节</template> · 原文件名未保存</div></div><div class="ui-actions"><Button size="small" :loading="reading===id" @click="preview(id)">授权预览</Button><Button v-if="editable" size="small" :disabled="disabled||loading||pending" @click="remove(index)">移除引用</Button></div></div><input v-if="editable" type="file" :accept="imagesOnly?'image/png,image/jpeg,image/webp':'image/png,image/jpeg,image/webp,application/pdf'" :disabled="disabled||loading||pending||ids.length>=maximum" @change="upload"/><p v-if="error" class="ui-error">{{error}}</p><div v-if="pending" class="ui-callout"><p>本次上传结果待确认。</p><Button :disabled="loading" @click="perform(()=>client.query())">回查上传</Button><Button :disabled="loading" @click="perform(()=>client.retry())">重试原上传</Button><Button :disabled="loading" @click="abandon">核实并关闭未提交上传</Button></div><Modal v-model="visible" :title="previewTitle" width="850" footer-hide @on-visible-change="visibleChanged"><div v-if="active"><img v-if="active.mimeType!=='application/pdf'" :src="active.url" alt="已授权附件预览" style="display:block;max-width:100%;max-height:65vh;margin:auto"/><div v-else><p>PDF文件，{{active.size}}字节。</p><a :href="active.url" target="_blank" rel="noopener noreferrer">打开本次已授权PDF</a></div></div></Modal></div></template>
<script>import {s1Uploads} from '@/api/stage1';import {uiPreview} from '@/api/stage1-usability';import {parent} from '../list-state.cjs';import {stage1Confirm} from '../../confirm';export default {inject:{stage1UploadActivity:{default:()=>()=>{}}},props:{value:[String,Array],title:String,purpose:{type:String,default:'QUALIFICATION'},scope:{type:String,default:'readonly'},editable:Boolean,multiple:Boolean,disabled:Boolean,imagesOnly:Boolean,maximum:{type:Number,default:10}},data(){const client=s1Uploads(parent(this.$route.path)+':'+this.scope);return {client,pending:client.pending(),loading:false,error:'',reading:null,metadata:{},active:null,visible:false,previewTitle:'授权附件',ticket:0};},computed:{ids(){return Array.isArray(this.value)?this.value:this.value?[this.value]:[];},purposeName(){return {GOODS:'商品图片',QUALIFICATION:'资质附件',AGREEMENT:'协议附件',CHANNEL:'进件附件'}[this.purpose]||'业务附件';}},watch:{value(){this.closePreview();}},mounted(){if(this.editable)this.stage1UploadActivity(this.scope,this.pending);},beforeDestroy(){this.closePreview();},methods:{async preview(id){const ticket=++this.ticket;this.reading=id;this.error='';try{const v=await uiPreview(id);if(ticket!==this.ticket){URL.revokeObjectURL(v.url);return;}if(this.active)URL.revokeObjectURL(this.active.url);this.active=v;this.$set(this.metadata,id,{mimeType:v.mimeType,size:v.size});this.previewTitle=this.purposeName+' · '+id;this.visible=true;}catch(e){if(ticket===this.ticket)this.error=e.message;}finally{if(ticket===this.ticket)this.reading=null;}},visibleChanged(open){if(!open)this.closePreview();},closePreview(){this.ticket++;if(this.active)URL.revokeObjectURL(this.active.url);this.active=null;this.visible=false;this.reading=null;},async perform(work){this.loading=true;this.error='';this.stage1UploadActivity(this.scope,true);try{const value=await work();if(value&&value.id){this.$emit('input',this.multiple?[...new Set([...this.ids,value.id])]:value.id);this.$set(this.metadata,value.id,{mimeType:value.mimeType,size:value.size});}}catch(e){this.error=e.message;}finally{this.loading=false;this.pending=this.client.pending();this.stage1UploadActivity(this.scope,this.pending);}},upload(event){const file=event.target.files[0];if(file)this.perform(()=>this.client.upload(file,this.purpose));event.target.value='';},remove(index){const values=[...this.ids];values.splice(index,1);this.$emit('input',this.multiple?values:null);},abandon(){stage1Confirm({title:'核实本次上传结果',content:'已提交时回读原文件；未提交时才关闭原请求。',onOk:()=>this.perform(()=>this.client.abandon())});}}};</script>
